PDM_ASSOCIATION_MAX_GAP_FRAMES = 3
# Outward margin applied to the ROADBLOCK copy of each T4 lane polygon.
#
# nuPlan's ROADBLOCK/DRIVABLE_AREA layer is the road surface - the lanes of a
# segment plus their shoulder - and DAC is computed against it.  T4 exports
# only painted-lane polygons (centre +/- the left/right offsets), so
# substituting a lane for a roadblock makes DAC strictly stricter than the
# metric it re-implements.  Measured with scripts/audit_t4_drivable_area.py
# and scripts/audit_t4_roadblock_buffer.py over 240 prd_jt windows, scoring
# the *human's own* recorded trajectory:
#
#   buffer   windows where the human is scored off-road
#   0.00 m   4.6 %   (10 of 11 already off-road at t=0, median 0.057 m outside)
#   0.10 m   2.1 %
#   0.20 m   1.2 %
#   0.50 m   0.4 %
#
# Because DAC is multiplicative, each such window drives every one of the 64
# proposals to total=0 and EP=0, and the cached pdm_progress to 0 (12.5 % of
# windows).  A margin of about 0.20 m removes most of that while staying far
# below a meaningful drivable-area infraction.
#
# The default stays 0.0 so the metric is unchanged unless it is opted into:
# this value feeds T4PDMReferenceConfig.signature, so raising it correctly
# invalidates an existing PDM reference cache, which must then be rebuilt with
# scripts/build_t4_pdm_reference_cache.py before training.
PDM_ROADBLOCK_BUFFER_M = 0.0
PDM_ASSOCIATION_BASE_GATE_M = 4.0


def _cfg_get(config: Any, key: str, default: Any = None) -> Any:
    if config is None:
        return default
    if hasattr(config, "get"):
        try:
            value = config.get(key, default)
            return default if value is None and default is not None else value
        except TypeError:
            pass
    try:
        value = config[key]
        return default if value is None and default is not None else value
    except (KeyError, TypeError, AttributeError):
        return getattr(config, key, default)


def _as_list(value: Any) -> list[Any]:
    if value is None:
        return []
    if isinstance(value, (str, bytes)):
        return [value]
    return list(value)


@dataclass(frozen=True)
class T4PDMReferenceConfig:
    """Immutable parameters that define one PDM reference cache."""

    future_num_poses: int = PDM_FUTURE_NUM_POSES
    proposal_num_poses: int = PDM_PROPOSAL_NUM_POSES
    interval_s: float = PDM_INTERVAL_S
    bridge_future_num_frames: int = PDM_BRIDGE_FUTURE_NUM_FRAMES
    map_radius_m: float = PDM_MAP_RADIUS_M
    # Part of the signature: the drivable-area margin changes NC/DAC and hence
    # the cached pdm_progress, so a cache built with a different value must be
    # rejected rather than silently mixed with freshly computed labels.
    roadblock_buffer_m: float = PDM_ROADBLOCK_BUFFER_M
    lateral_offsets_m: tuple[float, ...] = PDM_LATERAL_OFFSETS_M
    speed_limit_fractions: tuple[float, ...] = PDM_SPEED_LIMIT_FRACTIONS
    fallback_target_velocity_ms: float = PDM_FALLBACK_TARGET_VELOCITY_MS
    min_gap_m: float = PDM_MIN_GAP_M
    headway_s: float = PDM_HEADWAY_S
    accel_max: float = PDM_ACCEL_MAX
    decel_max: float = PDM_DECEL_MAX

    @classmethod
    def from_config(cls, config: Any = None) -> "T4PDMReferenceConfig":
        """Read optional overrides while retaining the original PDM defaults."""

        def floats(key: str, default: Sequence[float]) -> tuple[float, ...]:
            value = _cfg_get(config, key, default)
            return tuple(float(item) for item in _as_list(value))

        result = cls(
            future_num_poses=int(
                _cfg_get(config, "t4_pdm_future_num_poses", PDM_FUTURE_NUM_POSES)
            ),
            proposal_num_poses=int(
                _cfg_get(config, "t4_pdm_proposal_num_poses", PDM_PROPOSAL_NUM_POSES)
            ),
            interval_s=float(_cfg_get(config, "t4_pdm_interval_s", PDM_INTERVAL_S)),
            bridge_future_num_frames=int(
                _cfg_get(
                    config,
                    "t4_pdm_bridge_future_num_frames",
                    PDM_BRIDGE_FUTURE_NUM_FRAMES,
                )
            ),
            map_radius_m=float(
                _cfg_get(config, "t4_pdm_map_radius_m", PDM_MAP_RADIUS_M)
            ),
            roadblock_buffer_m=float(
                _cfg_get(config, "t4_drivable_area_buffer_m", PDM_ROADBLOCK_BUFFER_M)
            ),
            lateral_offsets_m=floats("t4_pdm_lateral_offsets_m", PDM_LATERAL_OFFSETS_M),
            speed_limit_fractions=floats(
                "t4_pdm_speed_limit_fractions", PDM_SPEED_LIMIT_FRACTIONS
            ),
            fallback_target_velocity_ms=float(
                _cfg_get(
                    config,
                    "t4_pdm_fallback_target_velocity_ms",
                    PDM_FALLBACK_TARGET_VELOCITY_MS,
                )
            ),
            min_gap_m=float(_cfg_get(config, "t4_pdm_min_gap_m", PDM_MIN_GAP_M)),
            headway_s=float(_cfg_get(config, "t4_pdm_headway_s", PDM_HEADWAY_S)),
            accel_max=float(_cfg_get(config, "t4_pdm_accel_max", PDM_ACCEL_MAX)),
            decel_max=float(_cfg_get(config, "t4_pdm_decel_max", PDM_DECEL_MAX)),
        )
        result.validate()
        return result

    def validate(self) -> None:
        if self.future_num_poses != 50 or self.proposal_num_poses != 40:
            raise ValueError(
                "T4 PDM reference preserves the original 50-pose future and "
                "40-pose proposal horizons"
            )
        if abs(self.interval_s - 0.1) > 1.0e-9:
            raise ValueError("T4 PDM reference must run at 10 Hz")
        if self.bridge_future_num_frames < self.future_num_poses:
            raise ValueError(
                "T4 PDM reference bridge horizon must cover the complete "
                f"{self.future_num_poses}-pose PDM future"
            )
        if self.map_radius_m <= 0.0:
            raise ValueError("T4 PDM map radius must be positive")
        if len(self.lateral_offsets_m) != 2:
            raise ValueError("T4 PDM reference requires the original two lateral offsets")
        if len(self.speed_limit_fractions) != 5:
            raise ValueError("T4 PDM reference requires the original five IDM policies")
        if any(value <= 0.0 for value in self.speed_limit_fractions):
            raise ValueError("T4 PDM speed-limit fractions must be positive")

    def payload(self) -> dict[str, Any]:
        payload = {
            "future_num_poses": self.future_num_poses,
            "proposal_num_poses": self.proposal_num_poses,
            "interval_s": self.interval_s,
            "bridge_future_num_frames": self.bridge_future_num_frames,
            "map_radius_m": self.map_radius_m,
            "lateral_offsets_m": list(self.lateral_offsets_m),
            "speed_limit_fractions": list(self.speed_limit_fractions),
            "fallback_target_velocity_ms": self.fallback_target_velocity_ms,
            "min_gap_m": self.min_gap_m,
            "headway_s": self.headway_s,
            "accel_max": self.accel_max,
            "decel_max": self.decel_max,
        }
        # Only present once the drivable-area margin is opted into, so caches
        # built before this field existed keep their signature and stay valid.
        # Any non-zero value produces a different signature and therefore a
        # hard cache-mismatch error instead of mixed labels.
        if self.roadblock_buffer_m != 0.0:
            payload["roadblock_buffer_m"] = self.roadblock_buffer_m
        return payload

    @property
    def signature(self) -> str:
        encoded = json.dumps(self.payload(), sort_keys=True, separators=(",", ":"))
        return hashlib.sha256(encoded.encode("utf-8")).hexdigest()


