def _object_array(values: Sequence[Any]) -> np.ndarray:
    result = np.empty((len(values),), dtype=object)
    for index, value in enumerate(values):
        result[index] = value
    return result


def _valid_segment_points(row: np.ndarray, *, min_points: int = 2) -> np.ndarray | None:
    values = np.asarray(row, dtype=np.float64)
    if values.ndim != 2 or values.shape[-1] < 8:
        return None
    valid = np.abs(values[:, :8]).sum(axis=-1) > 0.0
    points = values[valid]
    if points.shape[0] < min_points:
        return None
    return points


def _safe_polygon(ring: np.ndarray, *, min_points: int = 3) -> Polygon | None:
    values = np.asarray(ring, dtype=np.float64)
    if values.ndim != 2 or values.shape[-1] != 2:
        return None
    values = values[np.isfinite(values).all(axis=-1)]
    if values.shape[0] < min_points:
        return None
    # Remove consecutive duplicate vertices before constructing the polygon.
    keep = np.ones(values.shape[0], dtype=bool)
    if values.shape[0] > 1:
        keep[1:] = np.linalg.norm(np.diff(values, axis=0), axis=-1) > 1.0e-7
    values = values[keep]
    if values.shape[0] < min_points:
        return None
    polygon = Polygon(values)
    if polygon.is_empty or polygon.area <= 1.0e-8:
        return None
    if not polygon.is_valid:
        polygon = polygon.buffer(0)
    if polygon.is_empty or polygon.area <= 1.0e-8:
        return None
    if polygon.geom_type == "MultiPolygon":
        polygon = max(polygon.geoms, key=lambda item: item.area)
    return polygon


def _lane_polygon(row: np.ndarray) -> Polygon | None:
    points = _valid_segment_points(row)
    if points is None:
        return None
    center = points[:, :2]
    left = center + points[:, 4:6]
    right = center + points[:, 6:8]
    return _safe_polygon(np.concatenate((left, right[::-1]), axis=0))


def _route_path(route: np.ndarray) -> tuple[PDMPath, list[np.ndarray]]:
    """Build the PDM centerline from ordered T4 route rows."""

    states: list[StateSE2] = []
    centerline_rows: list[np.ndarray] = []
    for row in np.asarray(route):
        points = _valid_segment_points(row)
        if points is None:
            continue
        centerline = points[:, :2]
        centerline_rows.append(np.ascontiguousarray(centerline, dtype=np.float64))
        tangent = points[:, 2:4]
        headings = np.arctan2(tangent[:, 1], tangent[:, 0])
        for point, heading in zip(centerline, headings):
            state = StateSE2(float(point[0]), float(point[1]), float(heading))
            if states:
                previous = states[-1]
                if np.hypot(state.x - previous.x, state.y - previous.y) <= 1.0e-6:
                    continue
            states.append(state)
    if len(states) < 2:
        raise ValueError("T4 route has fewer than two usable centerline points")
    return PDMPath(states), centerline_rows


def _match_route_lanes(
    route_rows: Sequence[np.ndarray], lane_rows: Sequence[np.ndarray]
) -> list[int | None]:
    """Match route segments to the same geometries in the lane tensor."""

    lane_points = [_valid_segment_points(row) for row in lane_rows]
    route_points = [_valid_segment_points(row) for row in route_rows]
    result: list[int | None] = []
    used: set[int] = set()
    for route in route_points:
        if route is None:
            result.append(None)
            continue
        best_index: int | None = None
        best_score = float("inf")
        for index, lane in enumerate(lane_points):
            if lane is None or index in used:
                continue
            endpoint = float(
                np.linalg.norm(route[0, :2] - lane[0, :2])
                + np.linalg.norm(route[-1, :2] - lane[-1, :2])
            )
            # Route/lane exports normally share every point.  The endpoint
            # test is sufficient and remains robust to a different sampling
            # density in a future T4 export.
            if endpoint < best_score:
                best_score = endpoint
                best_index = index
        if best_index is not None and best_score <= 3.0:
            used.add(best_index)
            result.append(best_index)
        else:
            result.append(None)
    return result


def _build_drivable_map(
    frame: Mapping[str, np.ndarray],
    roadblock_buffer_m: float = PDM_ROADBLOCK_BUFFER_M,
) -> tuple[PDMDrivableMap, list[str], list[Polygon]]:
    """Convert T4 lane/route/intersection geometry to PDM map layers.

    ``roadblock_buffer_m`` widens only the ROADBLOCK copy of each lane, which
    is what ``DAC`` and the non-drivable-area mask are computed against.  The
    LANE copy stays exact because the single-lane and oncoming-traffic masks -
    and through them DDC and the at-fault collision classification - depend on
    the true lane boundary.  See ``PDM_ROADBLOCK_BUFFER_M`` for why this knob
    exists.
    """

    lanes = np.asarray(frame["lanes"])
    route = np.asarray(frame["route"])
    polygons = np.asarray(frame["polygons"])
    buffer_m = float(roadblock_buffer_m)
    if not np.isfinite(buffer_m) or buffer_m < 0.0:
        raise ValueError(
            f"T4 roadblock buffer must be finite and non-negative, got {roadblock_buffer_m}"
        )
    lane_entries: list[tuple[int, Polygon]] = []
    for index, row in enumerate(lanes):
        polygon = _lane_polygon(row)
        if polygon is not None:
            lane_entries.append((index, polygon))
    if not lane_entries:
        raise ValueError("T4 frame contains no usable lane polygons")

    lane_rows = [lanes[index] for index, _ in lane_entries]
    route_matches = _match_route_lanes(route, lanes)
    lane_token_by_source = {source: f"t4-lane-{source}" for source, _ in lane_entries}

    tokens: list[str] = []
    map_types: list[SemanticMapLayer] = []
    geometries: list[Polygon] = []
    for source, polygon in lane_entries:
        # PDM uses ROADBLOCK/INTERSECTION/etc. for the broad drivable-area
        # mask and LANE for the single-lane/oncoming mask.  T4 exports lane
        # polygons but not a separate roadblock polygon, so the same lane
        # geometry is deliberately registered in both semantic layers.  The
        # roadblock copy may be widened to recover the road surface that a
        # painted-lane polygon does not represent; the lane copy never is.
        roadblock = polygon.buffer(buffer_m) if buffer_m > 0.0 else polygon
        if roadblock.geom_type == "MultiPolygon":
            roadblock = max(roadblock.geoms, key=lambda item: item.area)
        tokens.extend((f"t4-roadblock-{source}", lane_token_by_source[source]))
        map_types.extend((SemanticMapLayer.ROADBLOCK, SemanticMapLayer.LANE))
        geometries.extend((roadblock, polygon))

    route_lane_ids: list[str] = []
    for match in route_matches:
        if match in lane_token_by_source:
            route_lane_ids.append(lane_token_by_source[int(match)])
            continue
        # A future exporter may decimate route rows differently from the
        # general lane tensor.  Keep that route geometry usable instead of
        # silently losing DDC/oncoming semantics; this branch is only taken
        # when endpoint matching failed, so it cannot duplicate a known lane.
        row_index = len(route_lane_ids)
        if row_index < len(route):
            polygon = _lane_polygon(route[row_index])
            if polygon is not None:
                token = f"t4-route-lane-{row_index}"
                tokens.extend((f"t4-route-roadblock-{row_index}", token))
                map_types.extend((SemanticMapLayer.ROADBLOCK, SemanticMapLayer.LANE))
                geometries.extend((polygon, polygon))
                route_lane_ids.append(token)

    intersection_polygons: list[Polygon] = []
    for index, row in enumerate(polygons):
        values = np.asarray(row, dtype=np.float64)
        valid = np.abs(values).sum(axis=-1) > 0.0
        ring = values[valid, :2]
        polygon = _safe_polygon(ring)
        if polygon is None:
            continue
        tokens.append(f"t4-intersection-{index}")
        map_types.append(SemanticMapLayer.INTERSECTION)
        geometries.append(polygon)
        intersection_polygons.append(polygon)

    if not route_lane_ids:
        raise ValueError("T4 route could not be matched to any lane polygon")
    return (
        PDMDrivableMap(tokens, map_types, _object_array(geometries)),
        route_lane_ids,
        intersection_polygons,
    )


def _red_light_polygons(route: np.ndarray) -> list[tuple[str, Polygon]]:
    result: list[tuple[str, Polygon]] = []
    for index, row in enumerate(np.asarray(route)):
        points = _valid_segment_points(row)
        if points is None or not bool((points[:, 10] > 0.5).any()):
            continue
        polygon = _lane_polygon(row)
        if polygon is not None:
            result.append((f"red_light_t4_route_{index}", polygon))
    return result


def _add_red_lights(observation: PDMObservation, route: np.ndarray) -> None:
    """Add T4's route-lane red one-hot as PDM red-light obstacles."""

    red_lights = _red_light_polygons(route)
    if not red_lights:
        return
    maps: list[PDMOccupancyMap] = []
    for occupancy in observation._occupancy_maps:  # PDMObservation has no public add-light API.
        tokens = list(occupancy.tokens)
        geometries = [occupancy[token] for token in tokens]
        tokens.extend(token for token, _ in red_lights)
        geometries.extend(polygon for _, polygon in red_lights)
        maps.append(PDMOccupancyMap(tokens, _object_array(geometries)))
    observation._occupancy_maps = maps


