def _associate_boxes(
    boxes_per_frame: Sequence[np.ndarray], labels_per_frame: Sequence[np.ndarray]
) -> list[list[str]]:
    """Associate T4 detections into stable tokens for PDM collision logic."""

    if len(boxes_per_frame) != len(labels_per_frame):
        raise ValueError("T4 box/label frame counts differ")
    next_token = 0
    tracks: dict[str, dict[str, Any]] = {}
    output: list[list[str]] = []
    for frame_index, (raw_boxes, raw_labels) in enumerate(
        zip(boxes_per_frame, labels_per_frame)
    ):
        boxes = np.asarray(raw_boxes, dtype=np.float64).reshape(-1, 9)
        labels = np.asarray(raw_labels, dtype=np.int64).reshape(-1)
        if boxes.shape[0] != labels.shape[0]:
            raise ValueError(f"T4 frame {frame_index} box/label count mismatch")
        active = [
            (token, state)
            for token, state in tracks.items()
            if frame_index - int(state["frame"]) <= PDM_ASSOCIATION_MAX_GAP_FRAMES
        ]
        assignment: list[str | None] = [None] * boxes.shape[0]
        if active and boxes.shape[0]:
            # Same cost matrix as the original per-track/per-box Python loops,
            # evaluated as array operations.  The gate, the label filter and
            # the constant-velocity prediction are unchanged, and the row order
            # still follows ``active`` so linear_sum_assignment breaks ties
            # identically.  This matters for throughput: the matrix is
            # tracks x boxes per frame over 51 frames, so the elementwise
            # Python version was the single most expensive part of building a
            # PDM observation and grew super-linearly with traffic density.
            previous = np.stack(
                [np.asarray(state["box"], dtype=np.float64) for _, state in active]
            )
            track_frames = np.array(
                [int(state["frame"]) for _, state in active], dtype=np.float64
            )
            track_labels = np.array(
                [int(state["label"]) for _, state in active], dtype=np.int64
            )
            elapsed = frame_index - track_frames
            predicted = previous[:, :2] + previous[:, 7:9] * (
                elapsed * PDM_INTERVAL_S
            )[:, None]
            speed = np.hypot(previous[:, 7], previous[:, 8])
            gate = np.maximum(
                PDM_ASSOCIATION_BASE_GATE_M,
                2.0 + speed * elapsed * PDM_INTERVAL_S * 2.0,
            )
            distance = np.linalg.norm(
                boxes[None, :, :2] - predicted[:, None, :], axis=-1
            )
            eligible = (track_labels[:, None] == labels[None, :]) & (
                distance <= gate[:, None]
            )
            cost = np.where(eligible, distance, 1.0e6)
            row_indices, column_indices = linear_sum_assignment(cost)
            for row_index, column_index in zip(row_indices, column_indices):
                if cost[row_index, column_index] >= 1.0e6:
                    continue
                assignment[int(column_index)] = active[int(row_index)][0]

        frame_tokens: list[str] = []
        for box_index, (box, label) in enumerate(zip(boxes, labels)):
            token = assignment[box_index]
            if token is None:
                token = f"t4-agent-{next_token:08d}"
                next_token += 1
            frame_tokens.append(token)
            tracks[token] = {
                "frame": frame_index,
                "box": np.asarray(box, dtype=np.float64).copy(),
                "label": int(label),
            }
        output.append(frame_tokens)
    return output


def _make_single_object(
    row: np.ndarray,
    label: int,
    token: str,
    timestamp_us: int,
) -> Any:
    """Build one nuPlan tracked object; the exact loop body of _make_objects."""

    object_type = _LABEL_TO_TYPE.get(int(label), TrackedObjectType.GENERIC_OBJECT)
    metadata = SceneObjectMetadata(
        timestamp_us=int(timestamp_us),
        token=str(token),
        track_id=None,
        track_token=str(token),
        category_name=_LABEL_TO_NAME.get(int(label), "generic_object"),
    )
    oriented_box = OrientedBox(
        StateSE2(float(row[0]), float(row[1]), float(row[6])),
        float(max(row[4], 1.0e-3)),
        float(max(row[3], 1.0e-3)),
        float(max(row[5], 1.0e-3)),
    )
    if object_type in {
        TrackedObjectType.VEHICLE,
        TrackedObjectType.BICYCLE,
        TrackedObjectType.PEDESTRIAN,
    }:
        return Agent(
            tracked_object_type=object_type,
            oriented_box=oriented_box,
            velocity=StateVector2D(float(row[7]), float(row[8])),
            metadata=metadata,
        )
    return StaticObject(
        tracked_object_type=object_type,
        oriented_box=oriented_box,
        metadata=metadata,
    )


def _make_objects(
    boxes: np.ndarray,
    labels: np.ndarray,
    tokens: Sequence[str],
    timestamp_us: int,
) -> list[Any]:
    objects: list[Any] = []
    boxes = np.asarray(boxes, dtype=np.float64).reshape(-1, 9)
    labels = np.asarray(labels, dtype=np.int64).reshape(-1)
    if boxes.shape[0] != labels.shape[0] or boxes.shape[0] != len(tokens):
        raise ValueError("T4 object/token/label counts differ")
    for row, label, token in zip(boxes, labels, tokens):
        objects.append(_make_single_object(row, int(label), str(token), timestamp_us))
    return objects

def make_t4_vehicle_and_ego(
    shape: np.ndarray,
    velocity: np.ndarray,
    acceleration: np.ndarray,
    steering: float = 0.0,
    yaw_rate: float = 0.0,
) -> tuple[VehicleParameters, EgoState]:
    """Build the nuPlan ego objects used by the original PDM evaluator.

    The T4 adapter keeps the vehicle dimensions and current dynamic state in
    the sample.  This helper is shared by PDM-Closed cache construction and by
    the training-time oracle so both paths use the same vehicle model.
    """

    shape = np.asarray(shape, dtype=np.float64).reshape(-1)
    if shape.shape != (3,) or not np.isfinite(shape).all():
        raise ValueError("T4 shape must be [wheelbase, length, width]")
    wheelbase, length, width = (float(value) for value in shape)
    if wheelbase <= 0.0 or length <= 0.0 or width <= 0.0:
        raise ValueError(f"invalid T4 vehicle shape {shape.tolist()}")
    vehicle = VehicleParameters(
        width=width,
        front_length=length / 2.0 + wheelbase / 2.0,
        rear_length=length / 2.0 - wheelbase / 2.0,
        cog_position_from_rear_axle=wheelbase / 2.0,
        wheel_base=wheelbase,
        vehicle_name="T4",
        vehicle_type="T4",
        height=float(length * 0.45),
    )
    velocity = np.asarray(velocity, dtype=np.float64).reshape(-1)
    acceleration = np.asarray(acceleration, dtype=np.float64).reshape(-1)
    if velocity.shape != (2,) or acceleration.shape != (2,):
        raise ValueError("T4 velocity and acceleration must each have shape [2]")
    ego = EgoState.build_from_rear_axle(
        rear_axle_pose=StateSE2(0.0, 0.0, 0.0),
        rear_axle_velocity_2d=StateVector2D(float(velocity[0]), float(velocity[1])),
        rear_axle_acceleration_2d=StateVector2D(
            float(acceleration[0]), float(acceleration[1])
        ),
        tire_steering_angle=steering,
        time_point=TimePoint(0),
        vehicle_parameters=vehicle,
        is_in_auto_mode=True,
        angular_vel=yaw_rate,
    )
    return vehicle, ego


def _make_vehicle_and_ego(reader: Any, center: int) -> tuple[VehicleParameters, EgoState]:
    """Build the PDM vehicle/ego objects from a direct T4 scene reader."""

    return make_t4_vehicle_and_ego(
        np.asarray(reader.scalars["shape"], dtype=np.float64),
        np.asarray(reader.scalars["velocity"][center], dtype=np.float64),
        np.asarray(reader.scalars["acceleration"][center], dtype=np.float64),
        float(np.asarray(reader.scalars["steering"])[center]),
        float(np.asarray(reader.scalars["yaw_rate"])[center]),
    )


def make_t4_ground_truth_observation(
    boxes: Sequence[np.ndarray],
    labels: Sequence[np.ndarray],
    *,
    trajectory_sampling: TrajectorySampling,
    proposal_sampling: TrajectorySampling,
) -> PDMObservation:
    """Create the metric-cache observation from T4 GT boxes.

    ``boxes`` contains the current frame followed by the future frames, all in
    the current ego frame. The metric cache scores a 4-second
    proposal with a 5-second, 10 Hz observation because TTC projects each
    proposal state one second ahead.  Consequently the normal input here has
    ``proposal_sampling.num_poses + 10 + 1`` frames (51 for the default grid).
    """

    if len(boxes) != len(labels):
        raise ValueError("T4 ground-truth box and label horizons differ")
    expected = max(
        trajectory_sampling.num_poses,
        proposal_sampling.num_poses + int(round(1.0 / proposal_sampling.interval_length)),
    ) + 1
    if len(boxes) != expected:
        raise ValueError(
            "T4 PDM observation requires current plus the original 5 s/10 Hz "
            f"GT window ({expected} frames), got {len(boxes)}"
        )

    tokens_per_frame = _associate_boxes(boxes, labels)

    # This fills PDMObservation exactly as ``update_detections_tracks`` would,
    # but without the nuPlan object detour.  The eager path built an Agent or
    # StaticObject for every box of every frame and then read a polygon and a
    # token back out; measured on the heaviest real window that detour was
    # 514 ms of the 1002 ms oracle call (make_objects 263 + tree update 251).
    # Only two things ever leave those objects: ``box.geometry`` -- computed
    # here vectorised with the exact ``translate_longitudinally_and_laterally``
    # arithmetic -- and ``unique_objects[token]``, which the collision
    # classifier touches for the handful of tokens that actually intersect a
    # proposal, and which is materialised lazily through the verbatim
    # ``_make_single_object``.  ``_make_t4_observation_reference`` keeps the
    # eager construction for the equivalence tests.
    observation = PDMObservation(
        trajectory_sampling,
        proposal_sampling,
        PDM_MAP_RADIUS_M,
        observation_sample_res=1,
    )
    occupancy_maps: list[PDMOccupancyMap] = []
    unique_spec: dict[str, tuple[int, np.ndarray, int]] = {}
    for frame_index, (frame_boxes, frame_labels, tokens) in enumerate(
        zip(boxes, labels, tokens_per_frame)
    ):
        rows = np.asarray(frame_boxes, dtype=np.float64).reshape(-1, 9)
        frame_label_values = np.asarray(frame_labels, dtype=np.int64).reshape(-1)
        # TrackedObjects sorts its contents by tracked_object_type.value with a
        # stable sort, so the eager occupancy maps carry tokens and geometries
        # in that order.  Query results are sets and the scorer keys on tokens,
        # but the replacement is kept structurally identical rather than merely
        # equivalent -- the equivalence test compares token lists verbatim.
        if rows.shape[0]:
            type_values = np.array(
                [
                    _LABEL_TO_TYPE.get(int(label), TrackedObjectType.GENERIC_OBJECT).value
                    for label in frame_label_values
                ]
            )
            order = np.argsort(type_values, kind="stable")
            rows = rows[order]
            frame_label_values = frame_label_values[order]
            tokens = [tokens[i] for i in order]
            polygons = list(shapely_creation.polygons(_t4_box_corners(rows)))
        else:
            polygons = []
        occupancy_maps.append(PDMOccupancyMap(list(tokens), polygons))
        for row, label, token in zip(rows, frame_label_values, tokens):
            if token not in unique_spec:
                unique_spec[token] = (frame_index * 100_000, row.copy(), int(label))
    assert len(occupancy_maps) == observation._observation_samples + 1, (
        f"Expected observation length {observation._observation_samples + 1}, "
        f"but got {len(occupancy_maps)}"
    )
    observation._occupancy_maps = occupancy_maps
    observation._unique_objects = _LazyUniqueObjects(unique_spec)
    observation._collided_track_ids = []
    observation._initialized = True
    return observation


def _t4_box_corners(rows: np.ndarray) -> np.ndarray:
    """FL, RL, RR, FR corners of every box; OrientedBox.geometry, vectorised.

    Mirrors ``_make_single_object``'s OrientedBox construction (length from
    column 4, width from column 3, both floored at 1e-3) and nuPlan's
    ``translate_longitudinally_and_laterally``:

        [(lat * cos(h + pi/2)) + (lon * cos(h)),
         (lat * sin(h + pi/2)) + (lon * sin(h))]

    evaluated with the same float64 expression structure so every coordinate
    is bit-identical to the per-object path (pinned by test).
    """

    rows = np.asarray(rows, dtype=np.float64).reshape(-1, 9)
    x, y, heading = rows[:, 0], rows[:, 1], rows[:, 6]
    half_length = np.maximum(rows[:, 4], 1.0e-3) / 2.0
    half_width = np.maximum(rows[:, 3], 1.0e-3) / 2.0
    half_pi = np.pi / 2.0
    cos_h, sin_h = np.cos(heading), np.sin(heading)
    cos_p, sin_p = np.cos(heading + half_pi), np.sin(heading + half_pi)
    corners = np.empty((rows.shape[0], 4, 2), dtype=np.float64)
    # all_corners() order: FRONT_LEFT, REAR_LEFT, REAR_RIGHT, FRONT_RIGHT.
    for index, (lon_sign, lat_sign) in enumerate(((1, 1), (-1, 1), (-1, -1), (1, -1))):
        lon = lon_sign * half_length
        lat = lat_sign * half_width
        corners[:, index, 0] = x + ((lat * cos_p) + (lon * cos_h))
        corners[:, index, 1] = y + ((lat * sin_p) + (lon * sin_h))
    return corners


class _LazyUniqueObjects(dict):
    """``unique_objects`` materialised on first access.

    The collision classifier reads ``unique_objects[token]`` only for tokens
    whose geometry actually intersects a proposal -- a handful per window --
    while the eager path constructed every object of every frame up front.
    ``__missing__`` builds the object for the token's first appearance with
    the verbatim ``_make_single_object``, so any token that is looked up is
    indistinguishable from the eager dict entry.
    """

    def __init__(self, spec: dict[str, tuple[int, np.ndarray, int]]):
        super().__init__()
        self._spec = spec

    def __missing__(self, token: str) -> Any:
        timestamp_us, row, label = self._spec[token]
        value = _make_single_object(row, label, token, timestamp_us)
        self[token] = value
        return value

    def __contains__(self, token: object) -> bool:
        return dict.__contains__(self, token) or token in self._spec

    def __len__(self) -> int:
        return len(self._spec)


def _make_t4_observation_reference(
    boxes: Sequence[np.ndarray],
    labels: Sequence[np.ndarray],
    *,
    trajectory_sampling: TrajectorySampling,
    proposal_sampling: TrajectorySampling,
) -> PDMObservation:
    """The original eager construction, kept as the equivalence oracle."""

    tokens_per_frame = _associate_boxes(boxes, labels)
    detections: list[DetectionsTracks] = []
    for frame_index, (frame_boxes, frame_labels, tokens) in enumerate(
        zip(boxes, labels, tokens_per_frame)
    ):
        objects = _make_objects(
            np.asarray(frame_boxes),
            np.asarray(frame_labels),
            tokens,
            frame_index * 100_000,
        )
        detections.append(DetectionsTracks(TrackedObjects(objects)))

    observation = PDMObservation(
        trajectory_sampling,
        proposal_sampling,
        PDM_MAP_RADIUS_M,
        observation_sample_res=1,
    )
    observation.update_detections_tracks(detections)
    return observation


def _transform_future_boxes(reader: Any, center: int, count: int) -> tuple[list[np.ndarray], list[np.ndarray]]:
    from t4_e2e_devkit.dataset.scene import (
        _bridge_stationary_boxes,
        _transform_agent_boxes_to_center,
    )

    center_pose = reader.trajectory[center]
    boxes: list[np.ndarray] = []
    labels: list[np.ndarray] = []
    for frame_index in range(center, center + count):
        frame = reader._gt_frame(frame_index)
        current_boxes = np.asarray(frame["gt_boxes"], dtype=np.float64).reshape(-1, 9)
        current_labels = np.asarray(frame["gt_labels"], dtype=np.int64).reshape(-1)
        boxes.append(
            _transform_agent_boxes_to_center(
                current_boxes, reader.trajectory[frame_index], center_pose
            )
        )
        labels.append(current_labels.copy())
    # The T4 annotation pipeline fills stationary tracker dropouts over the complete 8 s
    # source window before the first 4 s scorer view is sliced.
    boxes, labels = _bridge_stationary_boxes(boxes, labels)
    return boxes, labels


def _make_observations(
    reader: Any,
    center: int,
    route: np.ndarray,
    vehicle: VehicleParameters,
    ego: EgoState,
    config: T4PDMReferenceConfig,
) -> tuple[PDMObservation, PDMObservation]:
    # Bridge stationary-track dropouts over the complete T4 source
    # window, then expose only the original 5 s PDM observation to the
    # generator and scorer.
    boxes, labels = _transform_future_boxes(
        reader, center, config.bridge_future_num_frames + 1
    )
    tokens = _associate_boxes(boxes, labels)
    current_objects = _make_objects(boxes[0], labels[0], tokens[0], 0)
    current_tracks = DetectionsTracks(TrackedObjects(current_objects))

    trajectory_sampling = TrajectorySampling(
        num_poses=config.future_num_poses, interval_length=config.interval_s
    )
    proposal_sampling = TrajectorySampling(
        num_poses=config.proposal_num_poses, interval_length=config.interval_s
    )

    # PDM-Closed generation uses the original current-frame observation and
    # forecasts dynamic objects with PDMObservation.update (constant velocity).
    forecast = PDMObservation(
        trajectory_sampling, proposal_sampling, config.map_radius_m, observation_sample_res=1
    )
    forecast.update(ego, current_tracks, [], {})
    _add_red_lights(forecast, route)

    # Reference progress is scored against the recorded future observations,
    # not the forecast used by PDM-Closed to generate its candidate.
    gt_tracks: list[DetectionsTracks] = []
    for frame_index in range(config.future_num_poses + 1):
        objects = _make_objects(
            boxes[frame_index], labels[frame_index], tokens[frame_index], frame_index * 100_000
        )
        gt_tracks.append(DetectionsTracks(TrackedObjects(objects)))
    ground_truth = PDMObservation(
        trajectory_sampling, proposal_sampling, config.map_radius_m, observation_sample_res=1
    )
    ground_truth.update_detections_tracks(gt_tracks)
    return forecast, ground_truth


def _simulate(
    proposal_states: np.ndarray,
    ego: EgoState,
    vehicle: VehicleParameters,
    config: T4PDMReferenceConfig,
) -> np.ndarray:
    simulator = PDMSimulator(
        TrajectorySampling(
            num_poses=config.proposal_num_poses,
            interval_length=config.interval_s,
        )
    )
    # The upstream PDM simulator historically initializes its tracker with
    # Pacifica defaults and only replaces the motion model vehicle.  T4's
    # shape is part of the data contract, so use it in both halves of the
    # original LQR+bicycle closed-loop simulation.
    simulator._motion_model._vehicle = vehicle
    simulator._tracker._wheel_base = vehicle.wheel_base
    return simulator.simulate_proposals(proposal_states, ego)


def compute_t4_pdm_reference(
    reader: Any,
    center: int,
    config: T4PDMReferenceConfig | None = None,
) -> T4PDMReferenceResult:
    """Run the original PDM-Closed generator and build one reference label."""

    config = config or T4PDMReferenceConfig()
    config.validate()
    center = int(center)
    if center < 0 or center + config.bridge_future_num_frames >= reader.n_frames:
        raise IndexError(
            f"T4 PDM center {center} has insufficient future frames for the "
            f"{config.bridge_future_num_frames}-frame source window"
        )

    frame = reader.frame(center)
    route = np.asarray(frame["route"], dtype=np.float64)
    centerline, _ = _route_path(route)
    drivable_map, route_lane_ids, _ = _build_drivable_map(
        frame, roadblock_buffer_m=config.roadblock_buffer_m
    )
    vehicle, ego = _make_vehicle_and_ego(reader, center)
    forecast, ground_truth = _make_observations(
        reader, center, route, vehicle, ego, config
    )

    lateral_paths = [centerline]
    for offset in config.lateral_offsets_m:
        lateral_paths.append(
            PDMPath(parallel_discrete_path(centerline.discrete_path, offset=float(offset)))
        )
    policies = BatchIDMPolicy(
        speed_limit_fraction=list(config.speed_limit_fractions),
        fallback_target_velocity=float(config.fallback_target_velocity_ms),
        min_gap_to_lead_agent=float(config.min_gap_m),
        headway_time=float(config.headway_s),
        accel_max=float(config.accel_max),
        decel_max=float(config.decel_max),
    )
    proposal_manager = PDMProposalManager(lateral_paths, policies)
    route_speed = np.asarray(frame["route_speed"], dtype=np.float64).reshape(-1)
    route_has_speed = np.asarray(frame["route_has_speed"], dtype=bool).reshape(-1)
    speed_limit = None
    if route_speed.size and route_has_speed.size and bool(route_has_speed[0]):
        if np.isfinite(route_speed[0]) and route_speed[0] > 1.0e-3:
            speed_limit = float(route_speed[0])
    proposal_manager.update(speed_limit)

    generator = PDMGenerator(
        TrajectorySampling(
            num_poses=config.future_num_poses,
            interval_length=config.interval_s,
        ),
        TrajectorySampling(
            num_poses=config.proposal_num_poses,
            interval_length=config.interval_s,
        ),
    )
    proposal_states = generator.generate_proposals(ego, forecast, proposal_manager)
    forecast_simulated = _simulate(proposal_states, ego, vehicle, config)
    forecast_scorer = PDMScorer(
        TrajectorySampling(
            num_poses=config.proposal_num_poses,
            interval_length=config.interval_s,
        ),
        vehicle_parameters=vehicle,
    )
    proposal_scores = forecast_scorer.score_proposals(
        forecast_simulated,
        forecast,
        centerline,
        route_lane_ids,
        drivable_map,
    )
    if not np.isfinite(proposal_scores).all():
        raise ValueError(f"PDM-Closed produced non-finite proposal scores at center {center}")
    selected = int(np.argmax(proposal_scores))

    # Materialize the selected 5 s PDM trajectory for cache audits.  The first
    # 4 s is already generated; generate_trajectory fills the remaining 1 s
    # exactly as PDMClosedPlanner does.
    generator.generate_trajectory(selected)
    reference_trajectory = np.asarray(
        generator._state_array[selected, :, :3], dtype=np.float32
    ).copy()

    # Re-run the selected/generated candidate through the same simulator and
    # score it against the recorded T4 future.  This mirrors the original
    # metric-cache processing: the PDM-Closed trajectory is evaluated
    # with the future observation, and the denominator contains only the raw
    # centerline progress gated by NC×DAC.  TTC/comfort/DDC are not part of
    # ``pdm_progress`` in the original cache.
    # ``_simulate`` is deterministic for a fixed ego state, vehicle, and
    # proposal tensor.  The first simulation above is the same trajectory
    # array needed by the recorded-future oracle below; running the closed
    # loop a second time only duplicated the most expensive part of each
    # center's reference-label computation without changing any label.
    gt_simulated = forecast_simulated
    ground_truth_scorer = PDMScorer(
        TrajectorySampling(
            num_poses=config.proposal_num_poses,
            interval_length=config.interval_s,
        ),
        vehicle_parameters=vehicle,
    )
    ground_truth_scorer._reset(
        gt_simulated,
        ground_truth,
        centerline,
        route_lane_ids,
        drivable_map,
    )
    ground_truth_scorer._calculate_ego_area()
    ground_truth_scorer._calculate_no_at_fault_collision()
    ground_truth_scorer._calculate_drivable_area_compliance()
    ground_truth_scorer._calculate_progress()
    multiplicative = ground_truth_scorer._multi_metrics.prod(axis=0)
    raw_progress = float(
        ground_truth_scorer._progress_raw[selected] * multiplicative[selected]
    )
    nc = float(ground_truth_scorer._multi_metrics[0, selected])
    dac = float(ground_truth_scorer._multi_metrics[1, selected])
    pdm_progress = raw_progress
    values = (pdm_progress, raw_progress, nc, dac)
    if not np.isfinite(values).all() or any(value < 0.0 for value in values):
        raise ValueError(f"PDM-Closed reference metrics are invalid at center {center}: {values}")
    return T4PDMReferenceResult(
        pdm_progress=float(pdm_progress),
        reference_trajectory=reference_trajectory,
        selected_proposal=selected,
        proposal_scores=np.asarray(proposal_scores, dtype=np.float32).copy(),
        reference_nc=nc,
        reference_dac=dac,
        reference_raw_progress=raw_progress,
    )


class T4PDMReferenceCache:
    """Validated scene-level cache for PDM-Closed reference labels."""

    _ARRAYS = (
        "pdm_progress",
        "reference_trajectory",
        "selected_proposal",
        "proposal_scores",
        "reference_nc",
        "reference_dac",
        "reference_raw_progress",
        "valid",
    )

    def __init__(self, cache_dir: Path, metadata: Mapping[str, Any]):
        self.cache_dir = Path(cache_dir)
        self.metadata = dict(metadata)
        self.n_frames = int(self.metadata["n_frames"])
        self._arrays: dict[str, np.ndarray] = {}
        for name in self._ARRAYS:
            path = self.cache_dir / f"{name}.npy"
            if not path.is_file():
                raise FileNotFoundError(f"T4 PDM reference cache is incomplete: missing {path}")
            # Reference caches are immutable training inputs.  Read-only
            # mappings prevent one worker/rank from accidentally dirtying a
            # shared NVMe cache while still allowing the OS to share pages.
            self._arrays[name] = np.load(path, mmap_mode="r")
        expected = {
            "pdm_progress": (self.n_frames,),
            "reference_trajectory": (self.n_frames, PDM_FUTURE_NUM_POSES + 1, 3),
            "selected_proposal": (self.n_frames,),
            "proposal_scores": (self.n_frames, 15),
            "reference_nc": (self.n_frames,),
            "reference_dac": (self.n_frames,),
            "reference_raw_progress": (self.n_frames,),
            "valid": (self.n_frames,),
        }
        for name, shape in expected.items():
            if tuple(self._arrays[name].shape) != shape:
                self.close()
                raise ValueError(
                    f"T4 PDM reference cache {name} has {self._arrays[name].shape}, expected {shape}"
                )

    @staticmethod
    def cache_dir_for(scene_dir: Path, root: Path, cache_root: Path) -> Path:
        scene_dir = Path(os.path.abspath(scene_dir))
        root = Path(os.path.abspath(root))
        cache_root = Path(os.path.abspath(cache_root))
        try:
            relative = scene_dir.relative_to(root)
        except ValueError as exc:
            raise ValueError(
                f"T4 scene {scene_dir} is outside dataset root {root}; "
                "cannot derive a safe PDM reference-cache path"
            ) from exc
        return cache_root / relative

    @staticmethod
    def _source_signature(scene_dir: Path) -> dict[str, Any]:
        signature: dict[str, Any] = {}
        for relative in (
            Path("derived") / "frames.pack",
            Path("derived") / "scalars.npz",
            Path("route.json"),
        ):
            path = scene_dir / relative
            if path.is_file():
                stat = path.stat()
                key = str(relative).replace("/", "_").replace(".", "_")
                signature[f"{key}_size"] = int(stat.st_size)
                signature[f"{key}_mtime_ns"] = int(stat.st_mtime_ns)
        return signature

    @classmethod
    def open(
        cls,
        scene_dir: Path,
        root: Path,
        cache_root: Path,
        *,
        config: T4PDMReferenceConfig | None = None,
        require: bool = False,
        verify_source: bool = True,
    ) -> "T4PDMReferenceCache | None":
        config = config or T4PDMReferenceConfig()
        config.validate()
        cache_dir = cls.cache_dir_for(scene_dir, root, cache_root)
        meta_path = cache_dir / "meta.json"
        if not meta_path.is_file():
            if require:
                raise FileNotFoundError(
                    f"required T4 PDM reference cache is missing: {cache_dir}; "
                    "run scripts/build_t4_pdm_reference_cache.py first"
                )
            return None
        try:
            metadata = json.loads(meta_path.read_text())
            if int(metadata.get("version", -1)) != PDM_REFERENCE_CACHE_VERSION:
                raise ValueError(
                    f"unsupported T4 PDM cache version {metadata.get('version')}; "
                    f"expected {PDM_REFERENCE_CACHE_VERSION}"
                )
            if str(metadata.get("config_sha256")) != config.signature:
                raise ValueError(
                    "T4 PDM reference parameters differ from the cache: "
                    f"cache={metadata.get('config_sha256')}, expected={config.signature}"
                )
            if verify_source:
                expected = cls._source_signature(Path(scene_dir))
                for key, value in expected.items():
                    if int(metadata.get(key, -1)) != int(value):
                        raise ValueError(
                            f"T4 PDM cache source signature mismatch for {key}: "
                            f"cache={metadata.get(key)!r}, source={value!r}"
                        )
            return cls(cache_dir, metadata)
        except Exception:
            if require:
                raise
            return None

    def frame(self, index: int) -> dict[str, Any]:
        index = int(index)
        if not 0 <= index < self.n_frames:
            raise IndexError(index)
        if not bool(self._arrays["valid"][index]):
            raise ValueError(
                f"T4 PDM reference cache has no valid label for center frame {index}"
            )
        return {
            "pdm_progress": float(self._arrays["pdm_progress"][index]),
            "reference_trajectory": np.array(
                self._arrays["reference_trajectory"][index],
                dtype=np.float32,
                copy=True,
            ),
            "selected_proposal": int(self._arrays["selected_proposal"][index]),
            "proposal_scores": np.array(
                self._arrays["proposal_scores"][index], dtype=np.float32, copy=True
            ),
            "reference_nc": float(self._arrays["reference_nc"][index]),
            "reference_dac": float(self._arrays["reference_dac"][index]),
            "reference_raw_progress": float(
                self._arrays["reference_raw_progress"][index]
            ),
        }

    def has_frames(self, centers: Sequence[int]) -> bool:
        return not self.missing_frames(centers)

    def missing_frames(self, centers: Sequence[int]) -> list[int]:
        """Return requested centers without a valid immutable reference label."""

        missing: list[int] = []
        for value in centers:
            index = int(value)
            if not 0 <= index < self.n_frames or not bool(self._arrays["valid"][index]):
                missing.append(index)
        return missing

    def close(self) -> None:
        self._arrays.clear()


def build_t4_pdm_reference_cache(
    scene_dir: str | Path,
    root: str | Path,
    cache_root: str | Path,
    *,
    centers: Sequence[int] | None = None,
    config: T4PDMReferenceConfig | None = None,
    camera_names: Sequence[str] | None = None,
    frame_cache_root: str | Path | None = None,
    overwrite: bool = False,
) -> dict[str, Any]:
    """Build one atomic PDM reference cache from the direct T4 scene format."""

    from t4_e2e_devkit.dataset.scene import normalize_t4_camera_names

    scene_dir = Path(scene_dir).resolve()
    root = Path(root).resolve()
    cache_root = Path(cache_root).resolve()
    config = config or T4PDMReferenceConfig()
    config.validate()
    cache_root.mkdir(parents=True, exist_ok=True)
    cache_dir = T4PDMReferenceCache.cache_dir_for(scene_dir, root, cache_root)

    from t4_e2e_devkit.dataset.scene import T4SceneReader

    scene_names = json.loads((scene_dir / "derived" / "cam_names.json").read_text())
    selected_cameras = normalize_t4_camera_names(
        list(camera_names) if camera_names is not None else scene_names
    )
    reader_config: dict[str, Any] = {"camera_names": selected_cameras}
    if frame_cache_root is not None:
        reader_config["t4_frame_cache_dir"] = str(Path(frame_cache_root).resolve())
        reader_config["t4_frame_cache_required"] = False
    reader = T4SceneReader(scene_dir, root, reader_config)
    n_frames = int(reader.n_frames)
    if centers is None:
        centers = range(30, n_frames - config.bridge_future_num_frames)
    center_list = sorted({int(index) for index in centers})
    invalid = [
        index
        for index in center_list
        if index < 30 or index + config.bridge_future_num_frames >= n_frames
    ]
    if invalid:
        reader.close()
        raise ValueError(
            "T4 PDM cache centers outside the 30-history/80-frame source "
            f"window: {invalid[:8]}"
        )

    if cache_dir.exists() and not overwrite:
        existing = T4PDMReferenceCache.open(
            scene_dir,
            root,
            cache_root,
            config=config,
            require=False,
            verify_source=True,
        )
        if existing is not None and existing.has_frames(center_list):
            result = {
                "scene": str(scene_dir.relative_to(root)),
                "cache_dir": str(cache_dir),
                "n_frames": n_frames,
                "centers": len(center_list),
                "built": False,
            }
            existing.close()
            reader.close()
            return result
        if existing is not None:
            existing.close()
        reader.close()
        raise FileExistsError(
            f"incomplete T4 PDM cache exists at {cache_dir}; use --overwrite to rebuild it"
        )

    temp_dir = Path(tempfile.mkdtemp(prefix=f".{cache_dir.name}.tmp-", dir=str(cache_root)))
    arrays: dict[str, np.ndarray] = {}
    try:
        arrays["pdm_progress"] = np.lib.format.open_memmap(
            temp_dir / "pdm_progress.npy", mode="w+", dtype=np.float32, shape=(n_frames,)
        )
        arrays["reference_trajectory"] = np.lib.format.open_memmap(
            temp_dir / "reference_trajectory.npy",
            mode="w+",
            dtype=np.float32,
            shape=(n_frames, config.future_num_poses + 1, 3),
        )
        arrays["selected_proposal"] = np.lib.format.open_memmap(
            temp_dir / "selected_proposal.npy", mode="w+", dtype=np.int16, shape=(n_frames,)
        )
        arrays["proposal_scores"] = np.lib.format.open_memmap(
            temp_dir / "proposal_scores.npy", mode="w+", dtype=np.float32, shape=(n_frames, 15)
        )
        for name in ("reference_nc", "reference_dac", "reference_raw_progress"):
            arrays[name] = np.lib.format.open_memmap(
                temp_dir / f"{name}.npy", mode="w+", dtype=np.float32, shape=(n_frames,)
            )
        arrays["valid"] = np.lib.format.open_memmap(
            temp_dir / "valid.npy", mode="w+", dtype=bool, shape=(n_frames,)
        )
        for array in arrays.values():
            array[...] = 0

        for position, center in enumerate(center_list, start=1):
            result = compute_t4_pdm_reference(reader, center, config)
            arrays["pdm_progress"][center] = result.pdm_progress
            arrays["reference_trajectory"][center] = result.reference_trajectory
            arrays["selected_proposal"][center] = result.selected_proposal
            arrays["proposal_scores"][center] = result.proposal_scores
            arrays["reference_nc"][center] = result.reference_nc
            arrays["reference_dac"][center] = result.reference_dac
            arrays["reference_raw_progress"][center] = result.reference_raw_progress
            arrays["valid"][center] = True
            if position == 1 or position % 25 == 0 or position == len(center_list):
                print(
                    f"[T4-PDM] {scene_dir.name}: {position}/{len(center_list)} "
                    f"center={center} progress={result.pdm_progress:.3f}",
                    flush=True,
                )

        for array in arrays.values():
            array.flush()
        arrays.clear()
        metadata = {
            "version": PDM_REFERENCE_CACHE_VERSION,
            "scene": str(scene_dir.relative_to(root)),
            "n_frames": n_frames,
            "centers": center_list,
            "config": config.payload(),
            "config_sha256": config.signature,
            "fields": list(T4PDMReferenceCache._ARRAYS),
            **T4PDMReferenceCache._source_signature(scene_dir),
        }
        (temp_dir / "meta.json").write_text(json.dumps(metadata, indent=2) + "\n")
        if cache_dir.exists():
            if not overwrite:
                raise FileExistsError(f"T4 PDM cache appeared while building: {cache_dir}")
            shutil.rmtree(cache_dir)
        cache_dir.parent.mkdir(parents=True, exist_ok=True)
        os.replace(temp_dir, cache_dir)
        return {
            "scene": str(scene_dir.relative_to(root)),
            "cache_dir": str(cache_dir),
            "n_frames": n_frames,
            "centers": len(center_list),
            "built": True,
        }
    except Exception:
        arrays.clear()
        shutil.rmtree(temp_dir, ignore_errors=True)
        raise
    finally:
        reader.close()
